def get_evaluation_dataset():
    return EVALUATION_QA

def get_dataset_stats():
    ds = get_evaluation_dataset()
    by_type, by_scenario = {}, {}
    for item in ds:
        t = item["type"]
        s = item["scenario"]
        by_type[t] = by_type.get(t, 0) + 1
        by_scenario[s] = by_scenario.get(s, 0) + 1
    return {"total": len(ds), "by_type": by_type, "by_scenario": by_scenario}
